### Objective
Build a production-grade Application Preferences & Settings Manager in Flutter using `package:shared_preferences`. Demonstrate pre-warmed bootstrap dependency injection, type-safe settings wrappers, reactive theme and locale toggling, and clean preference clearing mechanics.

```dart
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() async {
  // 1. Ensure Flutter engine is attached before native platform calls
  WidgetsFlutterBinding.ensureInitialized();

  // 2. Pre-warm SharedPreferences during bootstrap before runApp()
  final sharedPreferences = await SharedPreferences.getInstance();
  final settingsRepo = SettingsRepository(sharedPreferences);

  runApp(PreferencesDemoApp(settingsRepository: settingsRepo));
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. SETTINGS REPOSITORY & DOMAIN MODEL
// ─────────────────────────────────────────────────────────────────────────────

enum AppThemePreference { system, light, dark }

class SettingsRepository {
  final SharedPreferences _prefs;

  static const String _keyThemeMode = 'app_theme_mode';
  static const String _keyNotifications = 'enable_notifications';
  static const String _keyUsername = 'user_display_name';
  static const String _keyLaunchCount = 'app_launch_count';

  SettingsRepository(this._prefs) {
    _incrementLaunchCount();
  }

  // Synchronous reads from in-memory cache
  AppThemePreference getThemePreference() {
    final raw = _prefs.getString(_keyThemeMode);
    return switch (raw) {
      'light' => AppThemePreference.light,
      'dark' => AppThemePreference.dark,
      _ => AppThemePreference.system,
    };
  }

  bool areNotificationsEnabled() => _prefs.getBool(_keyNotifications) ?? true;

  String getUsername() => _prefs.getString(_keyUsername) ?? 'Guest Explorer';

  int getLaunchCount() => _prefs.getInt(_keyLaunchCount) ?? 1;

  // Asynchronous persistent writes
  Future<bool> setThemePreference(AppThemePreference pref) {
    final value = switch (pref) {
      AppThemePreference.light => 'light',
      AppThemePreference.dark => 'dark',
      AppThemePreference.system => 'system',
    };
    return _prefs.setString(_keyThemeMode, value);
  }

  Future<bool> setNotificationsEnabled(bool enabled) {
    return _prefs.setBool(_keyNotifications, enabled);
  }

  Future<bool> setUsername(String name) {
    return _prefs.setString(_keyUsername, name.trim());
  }

  void _incrementLaunchCount() {
    final current = getLaunchCount();
    _prefs.setInt(_keyLaunchCount, current + 1);
  }

  Future<bool> resetAllPreferences() async {
    return await _prefs.clear();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. REACTIVE CONTROLLER
// ─────────────────────────────────────────────────────────────────────────────

class SettingsController extends ChangeNotifier {
  final SettingsRepository _repository;

  SettingsController(this._repository);

  AppThemePreference get themePreference => _repository.getThemePreference();
  bool get notificationsEnabled => _repository.areNotificationsEnabled();
  String get username => _repository.getUsername();
  int get launchCount => _repository.getLaunchCount();

  ThemeMode get themeMode => switch (themePreference) {
        AppThemePreference.light => ThemeMode.light,
        AppThemePreference.dark => ThemeMode.dark,
        AppThemePreference.system => ThemeMode.system,
      };

  Future<void> updateTheme(AppThemePreference pref) async {
    await _repository.setThemePreference(pref);
    notifyListeners();
  }

  Future<void> toggleNotifications(bool value) async {
    await _repository.setNotificationsEnabled(value);
    notifyListeners();
  }

  Future<void> updateUsername(String name) async {
    await _repository.setUsername(name);
    notifyListeners();
  }

  Future<void> reset() async {
    await _repository.resetAllPreferences();
    notifyListeners();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class PreferencesDemoApp extends StatefulWidget {
  final SettingsRepository settingsRepository;
  const PreferencesDemoApp({super.key, required this.settingsRepository});

  @override
  State<PreferencesDemoApp> createState() => _PreferencesDemoAppState();
}

class _PreferencesDemoAppState extends State<PreferencesDemoApp> {
  late final SettingsController _controller;

  @override
  void initState() {
    super.initState();
    _controller = SettingsController(widget.settingsRepository);
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: _controller,
      builder: (context, _) {
        return MaterialApp(
          title: 'SharedPreferences Settings',
          debugShowCheckedModeBanner: false,
          themeMode: _controller.themeMode,
          theme: ThemeData(
            colorSchemeSeed: Colors.teal,
            brightness: Brightness.light,
            useMaterial3: true,
          ),
          darkTheme: ThemeData(
            colorSchemeSeed: Colors.teal,
            brightness: Brightness.dark,
            useMaterial3: true,
          ),
          home: SettingsScreen(controller: _controller),
        );
      },
    );
  }
}

class SettingsScreen extends StatelessWidget {
  final SettingsController controller;
  const SettingsScreen({super.key, required this.controller});

  void _showEditNameDialog(BuildContext context) {
    final textController = TextEditingController(text: controller.username);

    showDialog(
      context: context,
      builder: (dialogCtx) => AlertDialog(
        title: const Text('Update Display Name'),
        content: TextField(
          controller: textController,
          decoration: const InputDecoration(labelText: 'Username', border: OutlineInputBorder()),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(dialogCtx), child: const Text('Cancel')),
          FilledButton(
            onPressed: () {
              controller.updateUsername(textController.text);
              Navigator.pop(dialogCtx);
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('App Preferences'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          _buildTelemetryCard(context),
          const SizedBox(height: 20),
          _buildAppearanceCard(context),
          const SizedBox(height: 20),
          _buildNotificationCard(context),
          const SizedBox(height: 24),
          OutlinedButton.icon(
            onPressed: () => controller.reset(),
            style: OutlinedButton.styleFrom(foregroundColor: Colors.redAccent),
            icon: const Icon(Icons.delete_sweep_rounded),
            label: const Text('Clear All Cached Preferences'),
          ),
        ],
      ),
    );
  }

  Widget _buildTelemetryCard(BuildContext context) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: ListTile(
        leading: const CircleAvatar(child: Icon(Icons.person_rounded)),
        title: Text(controller.username, style: const TextStyle(fontWeight: FontWeight.bold)),
        subtitle: Text('App Launch Sessions: ${controller.launchCount}'),
        trailing: IconButton(
          icon: const Icon(Icons.edit_rounded),
          onPressed: () => _showEditNameDialog(context),
        ),
      ),
    );
  }

  Widget _buildAppearanceCard(BuildContext context) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Appearance Theme', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
            const SizedBox(height: 6),
            const Text('Stored synchronously in in-memory SharedPreferences cache.', style: TextStyle(fontSize: 12, color: Colors.grey)),
            const SizedBox(height: 14),
            SegmentedButton<AppThemePreference>(
              segments: const [
                ButtonSegment(value: AppThemePreference.system, label: Text('System'), icon: Icon(Icons.brightness_auto)),
                ButtonSegment(value: AppThemePreference.light, label: Text('Light'), icon: Icon(Icons.light_mode)),
                ButtonSegment(value: AppThemePreference.dark, label: Text('Dark'), icon: Icon(Icons.dark_mode)),
              ],
              selected: {controller.themePreference},
              onSelectionChanged: (set) => controller.updateTheme(set.first),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildNotificationCard(BuildContext context) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SwitchListTile(
        title: const Text('Push Notifications', style: TextStyle(fontWeight: FontWeight.bold)),
        subtitle: const Text('Persisted boolean flag in platform NSUserDefaults / XML.'),
        value: controller.notificationsEnabled,
        onChanged: (val) => controller.toggleNotifications(val),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Pre-Warming in main() Before runApp()**:
   `final sharedPreferences = await SharedPreferences.getInstance();` is executed before `runApp()`. By the time Flutter paints the first frame, all preferences are in RAM. The app launches immediately into the correct theme mode (Light or Dark) without any visible flickering or frame flashes.
2. **Synchronous Getters**:
   In `SettingsRepository`, `getThemePreference()` executes synchronously in <0.1ms without requiring `FutureBuilder` widgets or loading spinners.
3. **Reactive UI Binding via ListenableBuilder**:
   The `SettingsController` extends `ChangeNotifier`. When a preference mutates, `notifyListeners()` triggers `ListenableBuilder` at the root of `PreferencesDemoApp`, instantly switching Flutter's `themeMode` dynamically across the entire widget tree.
